<template>
  <q-dialog :model-value="visible" @update:model-value="$emit('update:visible', $event)" persistent>
    <q-card :class="['test-result-card', { 'test-result-card--dark': $q.dark.isActive }]">
      <!-- Header -->
      <q-toolbar class="bg-primary text-white">
        <q-icon name="science" size="md" class="q-mr-sm" />
        <q-toolbar-title>
          {{ $t('workflow_test_results') }}
        </q-toolbar-title>
        <q-btn flat round dense icon="close" @click="$emit('update:visible', false)" />
      </q-toolbar>

      <q-card-section v-if="testResults">
        <!-- Overall Result Summary -->
        <div class="row q-mb-md q-pa-md rounded-borders" :class="getOverallResultClass()">
          <div class="col-12">
            <div class="row items-center">
              <q-icon
                :name="testResults.workflow_result === 'success' ? 'check_circle' : 'error'"
                :color="testResults.workflow_result === 'success' ? 'positive' : 'negative'"
                size="32px"
                class="q-mr-sm"
              />
              <div>
                <div class="text-h6">
                  {{ testResults.workflow_result === 'success' ? $t('test_passed') : $t('test_failed') }}
                </div>
                <div class="text-caption text-grey">
                  {{ workflowName }} •
                  <span style="cursor: help; border-bottom: 1px dotted currentColor">
                    {{ testResults.execution_time + 's' || '-' }}
                    <q-tooltip>{{ $t('wf_execution_time_includes_setup') }}</q-tooltip>
                  </span>
                </div>
              </div>
            </div>
          </div>
        </div>

        <!-- Node Execution Details -->
        <div class="text-subtitle1 q-mb-sm">
          {{ $t('node_execution_details') }}
        </div>

        <q-list bordered dense class="rounded-borders node-results-list">
          <q-expansion-item
            v-for="(log, idx) in testResults.logs"
            :key="idx"
            :ref="`node-${idx}`"
            :header-class="getNodeLogClass(log)"
            dense
            expand-separator
            @show="scrollToNode(idx)"
          >
            <template #header>
              <q-item-section side>
                <span class="node-log-index text-weight-medium">{{ idx + 1 }}</span>
              </q-item-section>
              <q-item-section avatar>
                <q-icon
                  :name="getNodeStatusIcon(log.status)"
                  :color="getNodeStatusColor(log.status)"
                  size="sm"
                />
              </q-item-section>

              <q-item-section>
                <q-item-label>
                  <span class="text-weight-medium">{{ formatNodeType(log.node_type) }}</span>
                  <span v-if="log.label && !isControlNode(log.node_type)" class="text-grey q-ml-xs">• {{ resolveCardLabel(log) }}</span>
                  <span v-else-if="log.label && isControlNode(log.node_type)" class="text-grey q-ml-xs">• {{ $t(log.label) }}</span>
                </q-item-label>
              </q-item-section>

              <q-item-section side>
                <q-badge :color="getNodeStatusColor(log.status)" outline>
                  {{ formatDuration(log.duration_ms) }}
                </q-badge>
              </q-item-section>
            </template>

            <!-- Expanded card logs -->
            <q-card flat class="log-details-card">
              <q-card-section v-if="log.logs && log.logs.length > 0" class="q-pa-sm">
                <div
                  v-for="(entry, entryIdx) in log.logs"
                  :key="entryIdx"
                  class="log-entry q-pa-xs q-mb-xs"
                  :class="getLogEntryClass(entry)"
                >
                  <div class="row items-start">
                    <q-icon
                      :name="getLogEntryIcon(entry)"
                      :color="getLogEntryColor(entry)"
                      size="xs"
                      class="q-mr-xs"
                    />
                    <span v-if="entry.translation_key" class="text-caption">
                      {{ $t('wf_log_' + entry.translation_key, translateData(entry.data)) }}
                    </span>
                    <span v-else class="text-caption">{{ entry.message }}</span>
                  </div>
                  <div v-if="isDebug && entry.data && Object.keys(entry.data).length > 0" class="q-ml-lg q-mt-xs">
                    <span
                      v-for="(value, key) in entry.data"
                      :key="key"
                      class="text-caption q-mr-sm"
                    >
                      <q-badge outline color="grey" class="q-mr-xs">{{ key }}</q-badge>
                      <span class="text-weight-medium">{{ value }}</span>
                    </span>
                  </div>
                </div>
              </q-card-section>
              <q-card-section v-else class="q-pa-sm text-caption text-grey">
                {{ $t('no_execution_logs') }}
              </q-card-section>
            </q-card>
          </q-expansion-item>

          <q-item v-if="!testResults.logs || testResults.logs.length === 0">
            <q-item-section class="text-grey text-center">
              {{ $t('no_execution_logs') }}
            </q-item-section>
          </q-item>
        </q-list>

        <!-- Execution Statistics -->
        <div class="row q-col-gutter-md q-mt-md">
          <div class="col-4">
            <q-card flat bordered class="text-center q-pa-sm">
              <div class="text-caption text-grey">{{ $t('total_nodes') }}</div>
              <div class="text-h6">{{ testResults.logs?.length || 0 }}</div>
            </q-card>
          </div>
          <div class="col-4">
            <q-card flat bordered class="text-center q-pa-sm">
              <div class="text-caption text-grey">{{ $t('successful') }}</div>
              <div class="text-h6 text-positive">
                {{ countNodesByStatus(NodeExecutionStatus.SUCCESS) }}
              </div>
            </q-card>
          </div>
          <div class="col-4">
            <q-card flat bordered class="text-center q-pa-sm">
              <div class="text-caption text-grey">{{ $t('failed') }}</div>
              <div class="text-h6 text-negative">
                {{ countNodesByStatus(NodeExecutionStatus.ERROR) + countNodesByStatus(NodeExecutionStatus.FAILED_CONDITION) }}
              </div>
            </q-card>
          </div>
        </div>
      </q-card-section>

      <!-- Actions -->
      <q-card-actions align="right" class="q-pa-md">
        <q-btn
          flat
          :label="$t('close')"
          color="grey-7"
          @click="$emit('update:visible', false)"
        />
        <q-btn
          flat
          icon="open_in_new"
          :label="$t('view_in_designer')"
          color="primary"
          @click="openInDesigner"
        />
        <q-btn
          flat
          icon="refresh"
          :label="$t('re_test')"
          color="primary"
          :loading="retesting"
          @click="retest"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent, PropType } from 'vue';
import { storeToRefs } from 'pinia';
import { useWorkflowBuilderStore } from 'src/store/main';
import type { AdvancedTestResponse, NodeExecutionLog } from '../workflow-advanced-models';
import { CONTROL_NODE_TYPES, PathResult, NodeExecutionStatus } from '../workflow-advanced-models';
import { workflowSplitDelimiter } from 'src/constants';
import { translateData } from '../composables/useNodeLogMessage';
import { maskSensitiveCardVariables } from '../composables/useCardVariableResolver';
import {
  getNodeStatusIcon,
  getNodeStatusColor,
  getLogEntryResult,
  getLogEntryIcon,
  getLogEntryColor,
  getLogEntryClass,
  formatDuration,
  formatNodeType,
} from '../composables/useNodeStatusDisplay';

export default defineComponent({
  name: 'WorkflowTestResultDialog',
  setup() {
    const store = useWorkflowBuilderStore();
    const { workflowModel } = storeToRefs(store);
    return {
      workflowModel,
      PathResult,
      NodeExecutionStatus,
      translateData,
      getNodeStatusIcon,
      getNodeStatusColor,
      getLogEntryResult,
      getLogEntryIcon,
      getLogEntryColor,
      getLogEntryClass,
      formatDuration,
      formatNodeType,
    };
  },

  props: {
    visible: {
      type: Boolean,
      required: true,
    },
    testResults: {
      type: Object as PropType<AdvancedTestResponse | null>,
      default: null,
    },
    workflowName: {
      type: String,
      default: '',
    },
    workflowId: {
      type: String,
      required: true,
    },
    nodes: {
      type: Array as PropType<any[]>,
      default: () => [],
    },
  },

  emits: ['update:visible', 'retest'],

  data() {
    return {
      retesting: false,
    };
  },

  computed: {
    isDebug(): boolean {
      return this.$route.query.debug !== undefined;
    },
  },

  methods: {
    getOverallResultClass() {
      return this.testResults?.workflow_result === PathResult.SUCCESS
        ? 'result-success'
        : 'result-error';
    },

    getNodeLogClass(log: any) {
      if (log.status === NodeExecutionStatus.ERROR) return 'result-error';
      if (log.status === NodeExecutionStatus.FAILED_CONDITION) return 'result-warning';
      if (log.status === NodeExecutionStatus.SKIPPED) return 'result-skipped';
      return '';
    },

    resolveCardLabel(log: any): string {
      const translated = this.$t(log.label) as string;
      if (!translated.includes(workflowSplitDelimiter)) return translated;

      // Find the canvas node matching this log entry
      const node = this.nodes.find((n: any) => n.id === log.node_id || n.data?.nodeId === log.node_id);
      const card = node?.data?.card;
      if (!card?.variables) return translated;

      // Mask sensitive DocOperator values before resolving
      maskSensitiveCardVariables(card);
      // Do NOT call populateWorkflowModelForCard here — the designer's normal flow
      // (processCardVariablesForLoad → initWorkFlowMode) already populated workflowModel.
      // Calling it would overwrite entries with _resolved: true, permanently blocking
      // Badge.vue's updateModel from responding to user changes in the designer.

      // Replace __%id__% placeholders with resolved display values
      let result = translated;
      for (const v of card.variables) {
        const placeholder = `${workflowSplitDelimiter}${v.id}${workflowSplitDelimiter}`;
        if (!result.includes(placeholder)) continue;

        const modelEntry = v.uuid ? this.workflowModel[v.uuid] : null;
        const displayValue = (modelEntry && modelEntry.badgeValue !== modelEntry.defaultValue)
          ? modelEntry.badgeValue
          : (v.data != null && v.data !== '')
            ? this.$t(String(v.data)) as string
            : this.$t(v.display_name) as string;

        result = result.replace(placeholder, displayValue);
      }
      return result;
    },
    isControlNode(nodeType: string): boolean {
      return (CONTROL_NODE_TYPES as readonly string[]).includes(nodeType?.toLowerCase());
    },

    countNodesByStatus(status: string): number {
      if (!this.testResults?.logs) return 0;
      return this.testResults.logs.filter((log: NodeExecutionLog) => log.status === status).length;
    },

    scrollToNode(idx: number) {
      // Wait for expansion animation to finish before scrolling
      setTimeout(() => {
        const ref = this.$refs[`node-${idx}`] as any;
        const el = (Array.isArray(ref) ? ref[0]?.$el : ref?.$el) as HTMLElement | undefined;
        const container = el?.closest('.node-results-list') as HTMLElement | null;
        if (el && container) {
          // Find log entries inside the expanded content
          const logEntries = el.querySelectorAll('.log-entry');
          // Target the 2nd or 3rd entry, or last one if fewer exist
          const targetIdx = Math.min(2, logEntries.length - 1);
          const targetEl = logEntries.length > 0 ? logEntries[targetIdx] as HTMLElement : null;

          if (targetEl) {
            const targetBottom = targetEl.offsetTop + targetEl.offsetHeight + el.offsetTop;
            const containerVisible = container.scrollTop + container.clientHeight;
            if (targetBottom > containerVisible) {
              container.scrollTo({
                top: targetBottom - container.clientHeight,
                behavior: 'smooth',
              });
            }
          }
        }
      }, 300);
    },

    openInDesigner() {
      this.$emit('update:visible', false);
      this.$router.push(`/advanced_workflow_designer/${this.workflowId}`);
    },

    async retest() {
      this.$emit('update:visible', false);
      this.$emit('retest', this.workflowId);
    },
  },
});
</script>

